cat > /tmp/pw/shot.mjs <<'EOF'
import { chromium } from 'playwright';
const [,, out = '/tmp/pw'] = process.argv;
const browser = await chromium.launch();
const page = await browser.newPage({ viewport: { width: 1400, height: 1300 } });
const errors = [];
page.on('console', (m) => m.type() === 'error' && errors.push(m.text()));
page.on('pageerror', (e) => errors.push(String(e)));
await page.goto('http://localhost:5173');
await page.evaluate(() => localStorage.clear());
await page.reload();
await page.waitForSelector('[data-widget-id="trend"]');
await page.waitForTimeout(400);
await page.screenshot({ path: `${out}/1-initial.png`, fullPage: true });

const box = async (id) => page.locator(`[data-widget-id="${id}"]`).boundingBox();
const pos = () => page.evaluate(() => JSON.parse(localStorage.getItem('viz-dashboard/v1')).items.map(i => `${i.i}:${i.x},${i.y},${i.w},${i.h}`).join(' '));
console.log('start ', await pos());

// hover line chart
const t = await box('trend');
await page.mouse.move(t.x + t.width * 0.6, t.y + t.height * 0.5);
await page.waitForTimeout(150);
await page.screenshot({ path: `${out}/2-hover.png`, clip: { x: t.x - 10, y: t.y - 10, width: t.width + 20, height: t.height + 20 } });

// drag "revenue" KPI header onto "aov" spot (move right by 9 cols)
const r = await box('revenue');
const a = await box('aov');
await page.mouse.move(r.x + 60, r.y + 20);
await page.mouse.down();
await page.mouse.move(r.x + 70, r.y + 25, { steps: 3 });
await page.mouse.move(a.x + 60, a.y + 20, { steps: 15 });
await page.waitForTimeout(250);
await page.screenshot({ path: `${out}/3-dragging.png` });
await page.mouse.up();
await page.waitForTimeout(300);
console.log('drag  ', await pos());

// drag the chart below the table (swap test)
const tr = await box('trend');
const pr = await box('products');
await page.mouse.move(tr.x + 200, tr.y + 20);
await page.mouse.down();
await page.mouse.move(tr.x + 210, tr.y + 30, { steps: 3 });
await page.mouse.move(tr.x + 200, pr.y + pr.height - 20, { steps: 20 });
await page.waitForTimeout(250);
await page.mouse.up();
await page.waitForTimeout(300);
console.log('swap  ', await pos());

// resize channels via corner: shrink height by ~2 rows
const ch = await box('channels');
await page.mouse.move(ch.x + ch.width - 6, ch.y + ch.height - 6);
await page.mouse.down();
await page.mouse.move(ch.x + ch.width - 6 - 120, ch.y + ch.height - 6 + 152, { steps: 15 });
await page.waitForTimeout(200);
await page.mouse.up();
await page.waitForTimeout(300);
console.log('resize', await pos());

// keyboard: focus goal grip, Shift+ArrowLeft x2, ArrowUp
await page.locator('[data-widget-id="goal"] .widget__grip').focus();
await page.keyboard.press('Shift+ArrowLeft');
await page.keyboard.press('ArrowUp');
await page.waitForTimeout(300);
console.log('keys  ', await pos());
console.log('live  ', await page.locator('[role=status][aria-live]').textContent());

// escape cancels
const g = await box('goal');
const before = await pos();
await page.mouse.move(g.x + 80, g.y + 18);
await page.mouse.down();
await page.mouse.move(g.x + 400, g.y + 300, { steps: 10 });
await page.keyboard.press('Escape');
await page.mouse.up();
console.log('esc unchanged:', before === await pos());

// add widget
await page.getByRole('button', { name: 'Добавить виджет' }).first().click();
await page.getByText('Выручка по каналам', { exact: true }).last().click();
await page.waitForTimeout(400);
console.log('added ', (await pos()).split(' ').length, 'items');

await page.screenshot({ path: `${out}/4-after.png`, fullPage: true });

// reload persists
const saved = await pos();
await page.reload();
await page.waitForTimeout(400);
console.log('persisted:', saved === await pos());

// narrow
await page.setViewportSize({ width: 500, height: 900 });
await page.waitForTimeout(300);
await page.screenshot({ path: `${out}/5-narrow.png` });

console.log('errors:', errors);
await browser.close();
EOF
